 async Task Snapshot(){if(role==0)return;var d=await Api(TargetPath("/api/gm/snapshot"));revision=Program.Str(d,"revision");inventoryRows.Clear();foreach(var o in Program.Rows(d,"items"))inventoryRows.Add(Program.Dict(o));goldSet.Value=Convert.ToDecimal(d["gold"]);ceraSet.Value=Convert.ToDecimal(d["cera"]);coinSet.Value=Convert.ToDecimal(d["coin"]);FillPoints(d,"skill_points",spSet,spAlt);RenderInventory();if(workspace.SelectedTab.Text=="VP技能")await LoadVP();}
 void FillPoints(Dictionary<string,object>d,string key,NumericUpDown a,NumericUpDown b){var values=Program.Rows(d,key).ToArray();if(values.Length==2){a.Value=Convert.ToDecimal(values[0]);b.Value=Convert.ToDecimal(values[1]);}else{a.Value=b.Value=0;}}
 void RenderInventory(){inventoryGrid.Rows.Clear();string q=bagQuery.Text.Trim();foreach(var row in inventoryRows){string c=Program.Str(row,"container");int f=bagFilter.SelectedIndex;if(f==1&&c!="items"&&c!="equipment")continue;if(f==2&&c!="worn")continue;if(f==3&&c!="special:1")continue;if(f==4&&c!="special:7"&&c!="pet_items")continue;if(q!=""&&Program.Str(row,"name").IndexOf(q,StringComparison.OrdinalIgnoreCase)<0&&!Program.Str(row,"template").Contains(q))continue;string craft="",forge="";if(row.ContainsKey("equipment")){var v=Program.Dict(row["equipment"]);craft=(Program.Str(v,"amplify")=="0"?"强化 +":"增幅 +")+Program.Str(v,"upgrade");forge=Program.Str(v,"refine");}int n=inventoryGrid.Rows.Add(ContainerLabel(c),Program.Str(row,"slot"),Program.Str(row,"template"),Program.Str(row,"name"),Program.Str(row,"amount"),craft,forge);inventoryGrid.Rows[n].Tag=row;}RenderInventoryTiles();}
 Dictionary<string,object> Selected(DataGridView g){if(g.SelectedRows.Count==0||g.SelectedRows[0].Tag==null)throw new Exception("请先选择一行。");return (Dictionary<string,object>)g.SelectedRows[0].Tag;}
 void SelectInventory(){if(inventoryGrid.SelectedRows.Count==0||inventoryGrid.SelectedRows[0].Tag==null)return;var row=Selected(inventoryGrid);ShowSelectedItem(row);editCount.Value=Math.Max(1,Convert.ToDecimal(row["amount"]));bool gear=row.ContainsKey("equipment");editCount.Enabled=!gear;foreach(var n in new[]{editUpgrade,editAmplify,editAmpValue,editForge})n.Enabled=gear;if(gear){var v=Program.Dict(row["equipment"]);editUpgrade.Value=Convert.ToDecimal(v["upgrade"]);editAmplify.Value=Convert.ToDecimal(v["amplify"]);editAmpValue.Value=Convert.ToDecimal(v["amplify_value"]);editForge.Value=Convert.ToDecimal(v["refine"]);}}
 object GearValues(NumericUpDown upgrade,NumericUpDown amplify,NumericUpDown value,NumericUpDown forge){return new{upgrade=upgrade.Value,amplify=amplify.Value,amplify_value=value.Value,refine=forge.Value};}
 async Task EditSelected(){var row=Selected(inventoryGrid);var values=new Dictionary<string,object>{{"container",row["container"]},{"slot",row["slot"]},{"template",row["template"]},{"amount",editCount.Value}};if(row.ContainsKey("equipment"))values["equipment"]=GearValues(editUpgrade,editAmplify,editAmpValue,editForge);await Command("item_edit",values,"修改 "+Program.Str(row,"name")+" (#"+Program.Str(row,"template")+")");}
 async Task DeleteSelected(){var row=Selected(inventoryGrid);await Command("item_delete",new{container=row["container"],slot=row["slot"],template=row["template"]},"删除 "+Program.Str(row,"name")+" ×"+Program.Str(row,"amount")+"。已穿戴物品需先卸下。");}
 string TargetPath(string path){if(account<=0||role<=0)throw new Exception("请先选择账号和角色。");return path+"?account="+account+"&character="+role;}
 async Task Command(string action,object values,string description){var body=Request(Reason(operationReason));foreach(var kv in Program.Parse(Program.Json.Serialize(values)))body[kv.Key]=kv.Value;body["action"]=action;if(revision!="")body["revision"]=revision;await Mutate("/api/gm/command",body,description);}
 void BuildMaterials(){var page=Page("晶体仓库");workspace.TabPages.Add(page);var p=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2};p.RowStyles.Add(new RowStyle(SizeType.Percent,100));p.RowStyles.Add(new RowStyle(SizeType.Absolute,90));page.Controls.Add(p);Grid(materialGrid,"编号","物品名字","仓库位置","数量");GridIcons(materialGrid,"template",1);p.Controls.Add(materialGrid,0,0);Number(materialCount,0,UInt32.MaxValue,0);var bottom=Flow();bottom.Controls.Add(Field("设为数量（账号共享）",materialCount));bottom.Controls.Add(Button("刷新",LoadMaterials));bottom.Controls.Add(Button("设置数量",SetMaterial,true));p.Controls.Add(bottom,0,1);materialGrid.SelectionChanged+=(s,e)=>{if(materialGrid.SelectedRows.Count>0&&materialGrid.SelectedRows[0].Tag!=null)materialCount.Value=Convert.ToDecimal(Selected(materialGrid)["amount"]);};}
 async Task LoadMaterials(){var d=await Api(TargetPath("/api/gm/materials"));materialGrid.Rows.Clear();foreach(var o in Program.Rows(d,"materials")){var row=Program.Dict(o);int i=materialGrid.Rows.Add(Program.Str(row,"template"),Program.Str(row,"name"),Program.Str(row,"space")+" / "+Program.Str(row,"slot"),Program.Str(row,"amount"));materialGrid.Rows[i].Tag=row;}}
 async Task SetMaterial(){var row=Selected(materialGrid);await Command("material_set",new{template=row["template"],value=materialCount.Value},Program.Str(row,"name")+" 账号仓库数量设为 "+materialCount.Value);await LoadMaterials();}
 void BuildQuests(){var page=Page("任务管理");workspace.TabPages.Add(page);var p=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3};p.RowStyles.Add(new RowStyle(SizeType.Absolute,56));p.RowStyles.Add(new RowStyle(SizeType.Percent,100));p.RowStyles.Add(new RowStyle(SizeType.Absolute,90));page.Controls.Add(p);NativeTheme.Cue(questQuery,"搜索任务名称或编号");StyleInput(questQuery);questQuery.Width=250;StyleInput(questFilter);questFilter.Width=135;questFilter.DropDownStyle=ComboBoxStyle.DropDownList;questFilter.Items.AddRange(new object[]{"全部","进行中","可提交","已完成","尚未接受"});questFilter.SelectedIndex=0;var top=Flow();top.Controls.Add(questQuery);top.Controls.Add(questFilter);top.Controls.Add(Button("查找任务",LoadQuests));p.Controls.Add(top,0,0);Grid(questGrid,"编号","任务名字","等级","状态","剩余目标","类型");questGrid.MultiSelect=true;p.Controls.Add(questGrid,0,1);var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};var buttons=Flow();buttons.Controls.Add(Button("标记可交",()=>QuestAction("quest_ready","标记目标完成"),true));buttons.Controls.Add(Button("完成 / 跳过（无奖励）",()=>QuestAction("quest_complete","完成或跳过任务，不发放奖励")));buttons.Controls.Add(Button("放弃选中任务",()=>QuestAction("quest_abandon","放弃进行中的任务")));bottom.Controls.Add(buttons);bottom.Controls.Add(Label("Ctrl / Shift 可多选；标记可交不会补提交材料；跳过不会发技能点、解锁槽位或觉醒奖励。"));p.Controls.Add(bottom,0,2);}
 async Task LoadQuests(){string[] filters={"","accepted","ready","completed","available"};var d=await Api(TargetPath("/api/gm/quests")+"&q="+Uri.EscapeDataString(questQuery.Text.Trim())+"&status="+filters[Math.Max(0,questFilter.SelectedIndex)]);questGrid.Rows.Clear();foreach(var o in Program.Rows(d,"quests")){var row=Program.Dict(o);string status=Program.Str(row,"status");status=status=="accepted"?"进行中":status=="ready"?"可提交":status=="completed"?"已完成":"未接受";int i=questGrid.Rows.Add(Program.Str(row,"id"),Program.Str(row,"name"),Program.Str(row,"level"),status,Program.Str(row,"progress"),Program.Str(row,"kind"));questGrid.Rows[i].Tag=row;}state.Text="当前显示 "+Program.Str(d,"returned")+" 个任务（最多500个，可用编号或名字筛选）。";}
 async Task QuestAction(string action,string description){var ids=questGrid.SelectedRows.Cast<DataGridViewRow>().Where(x=>x.Tag!=null).Select(x=>Convert.ToUInt16(((Dictionary<string,object>)x.Tag)["id"])).ToArray();if(ids.Length==0)throw new Exception("请选择任务。");await Command(action,new{ids},description+"："+String.Join(",",ids));await LoadQuests();}
 void BuildMail(){var page=Page("邮件管理");workspace.TabPages.Add(page);var p=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3};p.RowStyles.Add(new RowStyle(SizeType.Absolute,56));p.RowStyles.Add(new RowStyle(SizeType.Percent,100));p.RowStyles.Add(new RowStyle(SizeType.Absolute,155));page.Controls.Add(p);var top=Flow();top.Controls.Add(Button("刷新游戏邮箱",LoadMail));top.Controls.Add(Button("删除选中邮件",DeleteMail));p.Controls.Add(top,0,0);Grid(mailGrid,"邮件编号","发件人","正文","附件","状态","到期时间");mailGrid.MultiSelect=true;p.Controls.Add(mailGrid,0,1);var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};StyleInput(mailText);mailText.Width=430;mailText.MaxLength=200;mailText.Text="GM发放";Number(mailGold,0,UInt32.MaxValue,0);var fields=Flow();fields.Controls.Add(Field("正文",mailText));fields.Controls.Add(Field("金币附件",mailGold));bottom.Controls.Add(fields);var buttons=Flow();buttons.Controls.Add(Button("发送金币 / 文本邮件",SendMail,true));buttons.Controls.Add(Label("物品和装备请在发放页选择“游戏邮箱”。"));bottom.Controls.Add(buttons);p.Controls.Add(bottom,0,2);}
 async Task LoadMail(){var d=await Api(TargetPath("/api/gm/mailbox"));mailGrid.Rows.Clear();foreach(var o in Program.Rows(d,"mail")){var row=Program.Dict(o);int i=mailGrid.Rows.Add(Program.Str(row,"id"),Program.Str(row,"sender"),Program.Str(row,"text"),Program.Str(row,"attachments"),Program.Str(row,"status"),Program.Str(row,"expires_at"));mailGrid.Rows[i].Tag=row;}}
 async Task DeleteMail(){var ids=mailGrid.SelectedRows.Cast<DataGridViewRow>().Where(x=>x.Tag!=null).Select(x=>Convert.ToInt64(((Dictionary<string,object>)x.Tag)["id"])).ToArray();if(ids.Length==0)throw new Exception("请选择邮件。");await Command("mail_delete",new{mail_ids=ids},"删除 "+ids.Length+" 封邮件及其中尚未领取的附件");await LoadMail();}
