 void BuildAudit(){var page=Page("审计与备份");workspace.TabPages.Add(page);var cards=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true,AutoScroll=true};page.Controls.Add(cards);cards.Controls.Add(Card("操作记录","查看当前账号的修改记录与操作原因。",Label("发放、调整、删除均可追溯"),Button("查看操作记录",History,true)));cards.Controls.Add(Card("存档备份","修改前会自动创建备份，也可手动保存。",Label("备份覆盖当前版本完整存档"),Button("立即备份",Backup,true)));cards.Controls.Add(Card("备份列表","核对已生成的备份时间和保存位置。",Label("备份文件与玩家存档分开保存"),Button("查看备份列表",Backups)));ArrangeCards(cards);}

