 void BuildVP(){var page=Page("VP技能");workspace.TabPages.Add(page);var body=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};body.RowStyles.Add(new RowStyle(SizeType.Absolute,50));body.RowStyles.Add(new RowStyle(SizeType.Percent,100));body.RowStyles.Add(new RowStyle(SizeType.Absolute,90));page.Controls.Add(body);vpStatus.AutoSize=true;vpStatus.ForeColor=gold;vpStatus.Font=new Font(Font.FontFamily,11F,FontStyle.Bold);vpStatus.Text="选择角色后读取 VP 配置";vpStatus.Margin=new Padding(4,12,0,0);body.Controls.Add(vpStatus,0,0);var columns=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));body.Controls.Add(columns,0,1);for(int group=0;group<2;group++){var surface=new Surface{Dock=DockStyle.Fill,Margin=new Padding(0,0,group==0?14:0,0),Padding=new Padding(20)};columns.Controls.Add(surface,group,0);var stack=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,WrapContents=false,FlowDirection=FlowDirection.TopDown};surface.Controls.Add(stack);var title=Label(group==0?"技能进化":"技能强化",15);title.Font=new Font(Font.FontFamily,15,FontStyle.Bold);stack.Controls.Add(title);var hint=Label(group==0?"5 个槽位 · 每个进化消耗 1 点 VP":"3 个槽位 · 配置技能强化效果");hint.ForeColor=Muted;stack.Controls.Add(hint);var boxes=group==0?vpEvolve:vpEnhance;for(int i=0;i<boxes.Length;i++){var c=new DarkComboBox{DropDownStyle=ComboBoxStyle.DropDownList};StyleInput(c);c.Width=320;boxes[i]=c;stack.Controls.Add(Field("槽位 0"+(i+1),c));}stack.SizeChanged+=(sender,e)=>{foreach(Control field in stack.Controls)if(field is FlowLayoutPanel){foreach(Control child in field.Controls)if(child is ComboBox)child.Width=Math.Max(180,stack.ClientSize.Width-30);}};}var foot=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};var buttons=Flow();buttons.Controls.Add(Button("保存 VP 配置",()=>SaveVP(false),true));buttons.Controls.Add(Button("重新读取",LoadVP));buttons.Controls.Add(Button("重置 VP 配置",()=>SaveVP(true)));foot.Controls.Add(buttons);var note=Label("第三次觉醒后可用；保存会同步 VP 余额，重置保留 SP 与已学技能。");note.ForeColor=Muted;foot.Controls.Add(note);body.Controls.Add(foot,0,2);}

 async Task LoadVP(){vpReady=false;var d=await Api(TargetPath("/api/gm/vp"));bool unlocked=Convert.ToBoolean(d["unlocked"]);var allocation=Program.Dict(d["allocation"]);vpPreset=allocation.ContainsKey("preset")?Convert.ToByte(allocation["preset"]):(byte)0;vpStatus.Text=unlocked?"已解锁 · 当前剩余 VP："+Program.Str(d,"remaining")+" / 5":"尚未第三次觉醒，不能编辑VP配置";var candidates=Program.Rows(d,"candidates").Select(Program.Dict).ToArray();FillVP(vpEnhance,candidates,"enhance",Program.Rows(allocation,"intensions").ToArray());FillVP(vpEvolve,candidates,"evolve",Program.Rows(allocation,"options").ToArray());vpReady=unlocked;}
 void FillVP(ComboBox[] boxes,Dictionary<string,object>[] candidates,string group,object[] saved){for(int i=0;i<boxes.Length;i++){var box=boxes[i];box.Items.Clear();box.Items.Add(new VPOption{Choice=3,Text="未选择"});foreach(var row in candidates)foreach(var choice in Program.Rows(row,group))box.Items.Add(new VPOption{ID=Convert.ToUInt16(row["id"]),Choice=Convert.ToUInt32(choice),Text=Program.Str(row,"name")+"  (#"+Program.Str(row,"id")+" · 选项 "+choice+")"});box.SelectedIndex=0;if(i>=saved.Length)continue;var old=Program.Dict(saved[i]);ushort id=Convert.ToUInt16(old["ID"]);uint option=Convert.ToUInt32(old["Choice"]);if(id==0)continue;var selected=box.Items.Cast<VPOption>().FirstOrDefault(x=>x.ID==id&&x.Choice==option);if(selected==null){selected=new VPOption{ID=id,Choice=option,Text="已存配置 #"+id+" · 选项 "+option};box.Items.Add(selected);}box.SelectedItem=selected;}}
 object[] VPValues(ComboBox[] boxes,bool reset){return boxes.Select(x=>{var v=reset?new VPOption{Choice=3}:(VPOption)x.SelectedItem;if(v==null)throw new Exception("请先读取角色VP配置。");return (object)new{ID=v.ID,Choice=v.Choice};}).ToArray();}
 async Task SaveVP(bool reset){if(!vpReady)throw new Exception("请先读取已三觉角色的VP配置。");await Command("vp_set",new{vp=new{preset=vpPreset,intensions=VPValues(vpEnhance,reset),options=VPValues(vpEvolve,reset)}},reset?"重置当前角色的VP技能进化和强化配置":"保存当前角色的VP技能进化和强化配置");}
