  async Task Search(){string path="/api/items?limit=100&offset="+offset+"&q="+Uri.EscapeDataString(search.Text.Trim());if(mode=="equipment")path+="&kind=equipment";if(mode=="stackable")path+="&kind=stackable";if(mode=="avatar")path+="&kind=equipment&slot="+Uri.EscapeDataString("时装");if(mode=="talisman")path+="&raw_type="+Uri.EscapeDataString(subtype.SelectedIndex==0?"[talisman]":"[rune]");if(mode=="equipment"&&slot.SelectedIndex>0)path+="&slot="+Uri.EscapeDataString(slot.Text);if(rarity.SelectedIndex>0)path+="&rarity="+(rarity.SelectedIndex-1);if(min.Value>0)path+="&level_min="+min.Value;if(max.Value>0)path+="&level_max="+max.Value;var d=await f.Api(path);grid.Rows.Clear();foreach(var o in Program.Rows(d,"items")){var row=Program.Dict(o);int i=grid.Rows.Add(Program.Str(row,"id"),Program.Str(row,"name"),Program.Str(row,"type"),Program.Str(row,"level"),Program.Str(row,"rarity_label"));grid.Rows[i].Tag=row;}board.SetRows(grid.Rows.Cast<DataGridViewRow>().Where(x=>x.Tag!=null).Select(x=>(Dictionary<string,object>)x.Tag),"id","type","");pageLabel.Text="第 "+(offset/100+1)+" 页 · "+Program.Str(d,"count")+" 条";}
  async Task Grant(){if(id.Value<2)throw new Exception("请先搜索并选择物品，或输入有效物品编号。");var values=new Dictionary<string,object>{{"template",id.Value},{"amount",count.Value},{"mail",destination.SelectedIndex==1},{"message","GM发放"}};if(mode=="equipment")values["equipment"]=f.GearValues(upgrade,amplify,ampvalue,forge);await f.Command("item_grant",values,"发放物品 #"+id.Value+" ×"+count.Value+" → "+destination.Text);}
 }
